using System;
using System.ComponentModel.DataAnnotations;

namespace HCMv3.Careers.Dto;

/// <summary>
/// Completes a careers-portal password reset. Field-for-field the same contract as ASP.NET Zero's
/// <c>ResetPasswordInput</c>, because the reset code is generated by the same
/// <c>User.SetNewPasswordResetCode()</c> and mailed by the same <c>IUserEmailer</c>.
/// </summary>
public class CareersResetPasswordInput
{
    [Required]
    public long UserId { get; set; }

    [Required]
    [StringLength(328)]
    public string ResetCode { get; set; }

    [Required]
    [StringLength(128)]
    public string Password { get; set; }

    public DateTime ExpireDate { get; set; }

    public string CaptchaResponse { get; set; }
}
